var RO_SF=(function sfRuntime(G) {
  const C = G.C, $ = i => document.getElementById(i);
  const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
  const fmt = n => Math.round(Number(n) || 0).toLocaleString('zh-TW');
  const RATE = [100, 100, 100, 100, 90, 80, 60, 40, 30, 20], FEE = [0, 50, 50, 50, 50, 1000, 1000, 1000, 11600, 11600, 11600];   // 同 api.js REFINE_RATE／REFINE_FEE
  const S = { cid: null, t: null, tab: 'star', sel: null, aff: 0, msg: '', bad: false, busy: false, arm: 0, keys: null };
  const def = x => (G.ye() || {})[x.itemId];
  const kind = x => { const d = def(x); return !d || d.starter ? null : d.slot === 'weapon' ? 'weapon' : 'armor'; };
  const inSt = x => typeof x.owner === 'string' && x.owner.startsWith('@ks');
  const acc = () => G.et();
  const stars = x => Math.max(0, Math.min(C.max, x.star | 0));
  const mult = n => Math.pow(C.step, n);
  const ore = (k, lv) => C.ore[k][lv <= C.low ? 0 : 1];
  const isOpen = () => { const e = $('starforge'); return !!e && !e.classList.contains('hidden'); };

  function list() {
    const t = S.t; if (!t) return [];
    let bl; try { bl = G.blocked(t); } catch { bl = new Set(); }
    return t.inventory.filter(x => { try { return G.vis(t, x) && kind(x) && !inSt(x) && !bl.has(x.uid) && (S.tab === 'star' || x.quality === 4); } catch { return false; } })
      .sort((p, q) => Number(G.worn(t, q.uid)) - Number(G.worn(t, p.uid)) || gs(q) - gs(p));
  }
  const gs = x => { try { return G.gs(x, S.t); } catch { return 0; } };
  function dom() {
    if ($('starforge')) return;
    const st = document.createElement('style'); st.textContent = C.CSS; document.head.appendChild(st);
    document.body.insertAdjacentHTML('beforeend', `<div id="starforge" class="overlay hidden"><div class="ro-window smith-window">
      <div class="ro-title">升星／洗鍊</div>
      <div class="ro-body" style="display:block">
        <div class="sf-top"><button class="inv-chip" data-sft="star">升星</button><button class="inv-chip" data-sft="reroll">洗鍊（傳說）</button><span class="spacer"></span><span class="sf-mats" id="sf-mats"></span></div>
        <div class="smith-body" style="padding:0"><div class="smith-side"><div id="sf-list" class="cand-list"></div></div><div id="sf-detail" class="smith-detail"></div></div>
      </div>
      <div class="btn-row pad"><button class="ro-btn" id="sf-close">關閉</button><span class="spacer"></span><button class="ro-btn primary" id="sf-go">升星</button></div></div></div>`);
    $('sf-close').onclick = close;
    $('sf-go').onclick = go;
    for (const b of document.querySelectorAll('#starforge [data-sft]')) b.onclick = () => { S.tab = b.dataset.sft; S.sel = null; S.aff = 0; S.msg = ''; S.arm = 0; draw(); };
  }
  function mats() {
    const m = (acc() || {}).materials || {}, k = (acc() || {}).kafra | 0;
    const ids = S.tab === 'star' ? [...C.ore.weapon, ...C.ore.armor] : C.rore.weapon;
    return ids.map(i => `<span title="${esc(C.oreName[i] || G.ut(i))}"><img src="${G.img(i)}" alt="">${fmt(m[i] | 0)}</span>`).join('') + `<span>卡普拉點數 <b>${fmt(k)}</b></span>`;
  }
  function row(x) {
    const d = def(x), w = G.worn(S.t, x.uid);
    return `<div class="cand${x.quality ? ` q${x.quality}` : ''}${x.uid === S.sel ? ' sel' : ''}" data-uid="${esc(x.uid)}">
      <div class="ico"><img src="${G.img(x.itemId)}"></div>
      <div class="cand-info"><b style="color:${x.quality ? G.qc(x.quality) : 'inherit'}">${esc(G.os(x))}</b><small>${w ? '穿著中' : esc(kind(x) === 'weapon' ? '武器' : '防具・飾品')}</small></div>
      <div class="cand-side">${stars(x) ? `<span class="sf-star">★${stars(x)}</span>` : ''}<span class="gs">GS <b>${gs(x)}</b></span></div></div>`;
  }
  const head = x => {
    const s = G.ma(x), base = [s.atk ? `+${s.atk} ATK` : '', s.matk ? `+${s.matk} MATK` : '', s.def ? `DEF ${Math.round(s.def * 10) / 10}` : ''].filter(Boolean).join(' · ');
    return `<div class="eq-item"><img class="big" src="${G.img(x.itemId)}"><div class="eq-info">
      <div class="eq-name"><b style="color:${x.quality ? G.qc(x.quality) : 'inherit'}">${esc(G.os(x))}</b><span class="gs">GS <b>${gs(x)}</b></span></div>
      <span class="muted">${x.quality ? `${esc(G.oe()[x.quality].name)} · ` : ''}Tier ${x.tier || 1} · 升星 ★${stars(x)}／${C.max}（×${mult(stars(x)).toFixed(2)}）</span>
      ${base ? `<div class="base-stats">${base}</div>` : ''}</div></div>`;
  };
  function starDetail(x) {
    const lv = stars(x), max = lv >= C.max, k = kind(x), o = ore(k, Math.min(C.max, lv + 1)), have = ((acc() || {}).materials || {})[o] | 0;
    const fee = FEE[lv + 1] || 0, kafra = (acc() || {}).kafra | 0, p = max ? 0 : RATE[lv];
    const ladder = Array.from({ length: C.max }, (_, i) => { const n = i + 1; return `<span class="${[n <= lv ? 'done' : '', n === lv + 1 ? 'next' : '', RATE[i] < 100 ? 'risk' : ''].filter(Boolean).join(' ')}">★${n}<b>${RATE[i]}%</b></span>`; }).join('');
    let gain = '';
    if (!max) {
      const a = G.ma(x), b = G.ma({ ...x, star: lv + 1 }), L = [];
      const add = (k2, u, v) => { if (u !== v) L.push(`<span>${k2 ? `<b>${k2}</b> ` : ''}${esc(u)}</span><span>▶</span><i>${esc(v)}</i>`); };
      add('ATK', a.atk, b.atk); add('MATK', a.matk, b.matk); add('DEF', Math.round(a.def * 10) / 10, Math.round(b.def * 10) / 10);
      try { const u = G.cn(G.go(x)), v = G.cn(G.go({ ...x, star: lv + 1 })); u.forEach((s, i) => add('', s, v[i])); } catch {}
      gain = L.length ? `<div class="box-title">升到 ★${lv + 1}</div><div class="ref-gain">${L.join('')}</div>` : '';
    }
    const warn = max ? `<div class="ref-safe">已經 ★${C.max}（最高）。</div>` : p >= 100 ? `<div class="ref-safe">★1～★4 不會失敗。</div>` : `<div class="ref-warn">成功率 ${p}%。失敗會掉 1 星（裝備和卡片不會消失）。</div>`;
    return `${head(x)}
      <div class="ref-ores"><div class="ref-ore sel"><img src="${G.img(o)}"><span class="cand-info"><b>${esc(C.oreName[o] || G.ut(o))}</b><small>你有 ${fmt(have)}</small></span>${max ? '' : `<span class="pct">${p}%</span>`}</div></div>
      <div class="sf-fee${!max && kafra < fee ? ' bad' : ''}">${max ? '' : `手續費 ${fmt(fee)} 卡普拉點數（成功失敗都收；你有 ${fmt(kafra)}）`}</div>
      <div class="ref-ladder">${ladder}</div>${warn}${gain}
      <div class="sf-msg ${S.bad ? 'bad' : 'ok'}">${S.msg}</div>`;
  }
  const affText = a => {
    if (!a) return '';
    try { const t = G.aff(a); if (t && t.length) return t.join('、'); } catch {}   // 遊戲自己的文字（技能詞綴也有：「+17% 施毒 傷害」）
    if (a.stat === 'skill') return `技能詞綴：${esc(a.skill)} 傷害 +${Math.round((+a.value || 0) * 100)}%`;
    return esc(`${a.stat} +${a.value}`);
  };
  function rerollDetail(x) {
    const m = (acc() || {}).materials || {}, kafra = (acc() || {}).kafra | 0, k = kind(x);
    const ores = C.rore[k], use = ores.find(o => (m[o] | 0) > 0);
    const affs = Array.isArray(x.affixes) ? x.affixes : [];
    if (S.aff >= affs.length) S.aff = 0;
    return `${head(x)}
      <div class="box-title">選一條詞綴重抽（其他條不變，一定會換成不一樣的）</div>
      <div id="sf-affs">${affs.map((a, i) => `<div class="sf-aff${i === S.aff ? ' sel' : ''}" data-aff="${i}"><b>${i + 1}</b><span>${affText(a)}</span></div>`).join('')}</div>
      <div class="ref-ores">${ores.map(o => `<div class="ref-ore${o === use ? ' sel' : ''}"><img src="${G.img(o)}"><span class="cand-info"><b>${esc(C.oreName[o] || G.ut(o))}</b><small>你有 ${fmt(m[o] | 0)}</small></span></div>`).join('')}</div>
      <div class="sf-fee${kafra < C.rfee ? ' bad' : ''}">每次用 1 個（${esc(C.oreName[ores[0]])}優先，沒有就用${esc(C.oreName[ores[1]])}）＋手續費 ${fmt(C.rfee)} 卡普拉點數（你有 ${fmt(kafra)}）</div>
      <div class="sf-msg ${S.bad ? 'bad' : 'ok'}">${S.msg}</div>`;
  }
  function can(x) {
    if (!x || S.busy) return false;
    const m = (acc() || {}).materials || {}, kafra = (acc() || {}).kafra | 0;
    if (S.tab === 'star') { const lv = stars(x); return lv < C.max && (m[ore(kind(x), lv + 1)] | 0) > 0 && kafra >= (FEE[lv + 1] || 0); }
    return x.quality === 4 && Array.isArray(x.affixes) && x.affixes.length > 0 && C.rore[kind(x)].some(o => (m[o] | 0) > 0) && kafra >= C.rfee;
  }
  function draw() {
    if (!isOpen()) return;
    try { S.t = G.ze(S.cid); } catch {}
    const L = list();
    if (!L.some(x => x.uid === S.sel)) S.sel = L.length ? L[0].uid : null;
    for (const b of document.querySelectorAll('#starforge [data-sft]')) b.classList.toggle('active', b.dataset.sft === S.tab);
    $('sf-mats').innerHTML = mats();
    $('sf-list').innerHTML = L.length ? L.map(row).join('') : `<div class="empty-note">${S.tab === 'star' ? '沒有可以升星的裝備。' : '沒有傳說裝備。'}</div>`;
    for (const el of $('sf-list').querySelectorAll('.cand')) el.onclick = () => { S.sel = el.dataset.uid; S.aff = 0; S.msg = ''; S.arm = 0; draw(); };
    const x = L.find(i => i.uid === S.sel), D = $('sf-detail'), B = $('sf-go');
    D.innerHTML = x ? (S.tab === 'star' ? starDetail(x) : rerollDetail(x)) : `<div class="empty-note">${S.msg ? `<div class="sf-msg ${S.bad ? 'bad' : 'ok'}">${S.msg}</div>` : '選一件裝備。'}</div>`;
    for (const el of D.querySelectorAll('[data-aff]')) el.onclick = () => { S.aff = +el.dataset.aff; S.arm = 0; draw(); };
    const risky = x && (S.tab === 'reroll' || RATE[stars(x)] < 100);
    B.disabled = !can(x);
    B.textContent = !x ? (S.tab === 'star' ? '升星' : '洗鍊') : S.arm ? '確定？再按一次' : S.tab === 'star' ? (stars(x) >= C.max ? '已經最高' : `升星到 ★${stars(x) + 1}`) : `洗第 ${S.aff + 1} 條`;
    B.dataset.risky = risky ? '1' : '';
  }
  async function go() {
    const x = list().find(i => i.uid === S.sel);
    if (!can(x)) return;
    if ($('sf-go').dataset.risky && !S.arm) { S.arm = Date.now(); draw(); setTimeout(() => { if (S.arm && Date.now() - S.arm >= 2900) { S.arm = 0; draw(); } }, 3000); return; }
    S.arm = 0; S.busy = true; draw();
    const name = G.os(x);
    try {
      if (S.tab === 'star') {
        const lv = stars(x), r = await G.uc({ op: 'star', uid: x.uid });
        G.snd(r.ok ? 'bs_refinesuccess' : 'bs_refinefailed');
        S.bad = !r.ok;
        S.msg = r.ok ? `升星成功！${esc(name)} → ★${r.star}` : lv > 0 ? `升星失敗：掉回 ★${r.star}。` : '升星失敗（★0 不會再掉）。';
      } else {
        const idx = S.aff, before = affText((x.affixes || [])[idx]);
        const r = await G.uc({ op: 'reroll', uid: x.uid, idx, char: S.t && S.t.id != null ? S.t.id : S.cid });
        G.snd('bs_refinesuccess');
        S.bad = false; S.msg = `第 ${idx + 1} 條：${before} ▶ ${affText(r.affix)}`;
      }
    } catch (e) {
      S.bad = true; S.msg = esc(e && e.message ? e.message : String(e));
    }
    S.busy = false; draw(); G.wa();
  }
  function open() {
    dom();
    if (S.keys) window.removeEventListener('keydown', S.keys, true);
    S.keys = e => { if (e.key !== 'Escape' || !isOpen()) return; const d = $('npc-dialog'); if (d && !d.classList.contains('hidden')) return; e.stopImmediatePropagation(); close(); };
    window.addEventListener('keydown', S.keys, true);
    S.msg = ''; S.arm = 0;
    G.ue('starforge');
    draw();
  }
  function close() {
    if (S.keys) { window.removeEventListener('keydown', S.keys, true); S.keys = null; }
    if (!isOpen()) return;
    G.ce('starforge'); G.wa();
  }
  // 鐵匠視窗打開時：在按鈕列加「升星／洗鍊」（只在連線中）
  function smith(cid) {
    S.cid = cid;
    try {
      const go = $('smith-go'); if (!go) return;
      let b = $('smith-star');
      if (!b) { b = document.createElement('button'); b.className = 'ro-btn'; b.id = 'smith-star'; b.textContent = '升星／洗鍊'; go.parentNode.insertBefore(b, go); b.onclick = open; }
      b.classList.toggle('hidden', !G.rr());
    } catch (e) { console.error('[starforge]', e); }
  }
  return { smith, open, close, isOpen };
})
